// file: server.js

const http = require('http');

const server = http.createServer((req, res) => {
    // Генерация ответа с кодом 404
    res.statusCode = 404;
    res.setHeader('Content-Type', 'text/plain; charset=utf-8');
    res.end('404 Not Found');
});

const PORT = 3000;
server.listen(PORT, () => {
    console.log(`Сервер запущен на http://localhost:${PORT}`);
});

/*
 * ========== ТЕОРИЯ ==========
 * 
 * 1. http.createServer() - создаёт HTTP-сервер
 *    - Принимает колбэк (req, res) => {}
 *    - req - объект запроса (информация от клиента)
 *    - res - объект ответа (что отправляем клиенту)
 * 
 * 2. res.statusCode = 404 - устанавливаем HTTP статус-код
 *    - 404 означает "Not Found" (ресурс не найден)
 *    - Другие коды: 200 (OK), 500 (ошибка сервера) и т.д.
 * 
 * 3. res.setHeader() - устанавливаем заголовки ответа
 *    - 'Content-Type' говорит браузеру, какой тип данных отправляем
 *    - 'text/plain' - обычный текст
 *    - 'charset=utf-8' - кодировка для поддержки кириллицы
 * 
 * 4. res.end() - завершаем ответ и отправляем тело
 *    - Внутри передаём строку, которую увидит клиент
 * 
 * 5. server.listen(PORT) - запускаем сервер на порту 3000
 *    - Порт - это "дверь", через которую приходят запросы
 *    - 3000 - стандартный порт для разработки
 * 
 * ========== КАК ТЕСТИРОВАТЬ ==========
 * 
 * 1. Запустить сервер:
 *    node server.js
 * 
 * 2. Открыть браузер и перейти по адресу:
 *    http://localhost:3000
 * 
 * 3. Ожидаемый результат:
 *    - В браузере увидите текст "404 Not Found"
 *    - В консоли сервера появится сообщение "Сервер запущен на http://localhost:3000"
 * 
 * 4. Альтернативный способ тестирования - через curl в терминале:
 *    curl -i http://localhost:3000
 *    - Флаг -i покажет заголовки ответа
 *    - Вы увидите статус 404 и текст ответа
 * 
 * 5. Проверка статуса через инструменты разработчика в браузере:
 *    - Нажать F12 -> вкладка Network
 *    - Обновить страницу
 *    - Найти запрос к localhost:3000
 *    - В колонке Status увидите 404
 */




// 1. Протокол HTTP, основные свойства HTTP, структура запроса и ответа. Форматы MIME. Типы заголовков. Статусы ответов. Cookie (атрибуты set-cockie). Параметры запроса. Переадресация. Форматы данных: application/x-www-form-urlencoded, multipart/form-data. Переадресация.
// Протокол HTTP и его основные свойства HTTP — протокол прикладного уровня, предназначенный для описания правил пересылки сообщений между клиентом и сервером. Действующим текстовым стандартом является версия HTTP/1.1, тогда как HTTP/2 представляет собой бинарный формат,. Особенности HTTP/2 включают:
// Данные передаются в бинарном формате в виде фреймов.
// Мультиплексирование: в рамках одного соединения поддерживается множество стримов (потоков),. У каждого фрейма есть свой номер и идентификатор потока (stream id), в котором он передается,. Последовательность фреймов важна только в рамках одного стрима,.
// Сжатие заголовков (HPACK): заголовки передаются в сжатом виде.
